messages.content:
Requirements (JSON records in document order; dependencies list the prerequisite requirement ids):
[
{
"id": "ROOT",
"type": "FOLDER",
"name": "BookStack Knowledge Base System",
"description": "Web-based knowledge base system for browsing, organizing, and reading shelves, books, chapters, and pages.",
"dependencies": []
},
{
"id": "REQ-1",
"type": "FOLDER",
"name": "Homepage",
"description": "Default landing page of the system. It presents the global navigation bar, search input, and visible entry points to core areas of the product. Reference image",
"dependencies": [],
"parent": "ROOT"
},
{
"id": "REQ-1.1",
"type": "ATOMIC",
"name": "Open Homepage",
"description": "Open the application and display the homepage. The page contains exactly one visible heading with accessible name `BookStack`.",
"dependencies": [],
"parent": "REQ-1",
"scenarios": [
{
"name": "Open Homepage",
"steps": [
"GIVEN: The system is accessible.",
"WHEN: The user opens the application URL.",
"THEN: The homepage is displayed as the default page with exactly one visible heading named `BookStack`."
]
}
]
},
{
"id": "REQ-1.2",
"type": "ATOMIC",
"name": "Back to Homepage from Other Pages",
"description": "Return to the homepage by activating exactly one button with accessible name `BookStack` in the global navigation. The button is keyboard accessible and is present on every non-homepage page used by this benchmark.",
"dependencies": [
"REQ-1.1"
],
"parent": "REQ-1",
"scenarios": [
{
"name": "Back to Homepage from Other Pages",
"steps": [
"GIVEN: The user is on a non-homepage page and the global navigation bar is visible.",
"WHEN: The user activates the unique button named `BookStack` in the global navigation.",
"THEN: The system navigates to the homepage, where exactly one visible heading named `BookStack` is present."
]
}
]
},
{
"id": "REQ-2",
"type": "FOLDER",
"name": "User Authentication and Session",
"description": "Provides login entry and authenticated session state. The login page and the authenticated homepage state follow the referenced layouts. Login page Homepage after login",
"dependencies": [
"REQ-1"
],
"parent": "ROOT"
},
{
"id": "REQ-2.1",
"type": "ATOMIC",
"name": "Enter Login Page",
"description": "Open the login form from the homepage navigation bar. The login page contains exactly one visible heading named `Login` and exactly one form with role `form` and accessible name `Login form`.",
"dependencies": [
"REQ-1.1"
],
"parent": "REQ-2",
"scenarios": [
{
"name": "Enter Login Page",
"steps": [
"GIVEN: The user is on the homepage and is not logged in.",
"WHEN: The user activates the unique link or button named `Login` in the homepage navigation bar.",
"THEN: The system displays the login form page with exactly one visible heading named `Login` and a form named `Login form`."
]
}
]
},
{
"id": "REQ-2.2",
"type": "ATOMIC",
"name": "Log In Successfully",
"description": "Authenticate with valid credentials and enter the authenticated homepage state. Seed data: verified account with nickname \"BookStack User\", email \"bookstack_user@example.com\", and password \"Password123!\".",
"dependencies": [
"REQ-2.1"
],
"parent": "REQ-2",
"scenarios": [
{
"name": "Log In Successfully",
"steps": [
"GIVEN: The user is on the login form page.",
"WHEN: The user enters `bookstack_user@example.com` in the uniquely labelled email textbox `Email address`, enters `Password123!` in the uniquely labelled password textbox `Password`, checks the checkbox named `Remember Me`, and activates the `Login` button inside the `Login form`.",
"THEN: The system logs the user in, returns to the homepage, and displays the nickname `BookStack User` in the authenticated navigation area."
]
}
]
},
{
"id": "REQ-3",
"type": "FOLDER",
"name": "Authenticated Homepage Dashboard",
"description": "Authenticated homepage dashboard that shows recent drafts, recently viewed items, most viewed favorites, recently updated pages, recent activity, and the dashboard controls shown in the reference image. Reference image",
"dependencies": [
"REQ-2"
],
"parent": "ROOT"
},
{
"id": "REQ-3.1",
"type": "ATOMIC",
"name": "Enter Authenticated Homepage",
"description": "Display the dashboard layout after a successful login, including four visible named regions or headings: \"My Recent Drafts\", \"My Recently Viewed\", \"My Most Viewed Favorites\", and \"Recently Updated Pages\". Seed data: verified account with nickname \"BookStack User\", email \"bookstack_user@example.com\", and password \"Password123!\".",
"dependencies": [
"REQ-2.2"
],
"parent": "REQ-3",
"scenarios": [
{
"name": "Enter Authenticated Homepage",
"steps": [
"GIVEN: The user has logged in successfully.",
"WHEN: The system finishes the post-login navigation.",
"THEN: The authenticated homepage dashboard is displayed with visible headings or named regions exactly matching \"My Recent Drafts\", \"My Recently Viewed\", \"My Most Viewed Favorites\", and \"Recently Updated Pages\"."
]
}
]
},
{
"id": "REQ-4",
"type": "FOLDER",
"name": "Shelves Module",
"description": "Shelves are top-level content containers with name, description, related books, and tags. This module covers listing shelves, opening shelf details, creating shelves, editing shelves, and deleting shelves. Shelf list page",
"dependencies": [
"REQ-1"
],
"parent": "ROOT"
},
{
"id": "REQ-4.1",
"type": "ATOMIC",
"name": "View Shelf List",
"description": "Open the shelf list page from the global navigation bar. The navigation control may be a link or button named exactly \"Shelves\". The page exposes a visible heading \"Shelves\" and a named region \"Shelf list\" containing the seeded shelf \"Shelf 4.1\" as a unique link or button with that accessible name.",
"dependencies": [
"REQ-1.1"
],
"parent": "REQ-4",
"scenarios": [
{
"name": "View Shelf List",
"steps": [
"GIVEN: The user is on a page where the global navigation bar is visible.",
"WHEN: The user activates the unique link or button named `Shelves` in the top navigation bar.",
"THEN: The system displays the shelf list page with heading `Shelves` and a unique shelf entry named `Shelf 4.1` in the `Shelf list` region."
]
}
]
},
{
"id": "REQ-4.2",
"type": "FOLDER",
"name": "Shelf Details Page",
"description": "Shelf details page that shows shelf information, included books, and the related action panel. Reference image",
"dependencies": [
"REQ-4.1"
],
"parent": "REQ-4"
},
{
"id": "REQ-4.2.1",
"type": "ATOMIC",
"name": "Enter Shelf Details Page",
"description": "Open the details page of a shelf from the shelf list. The shelf list contains the shelf as a unique link or button named exactly \"Shelf 4.2.1\". The destination displays a visible heading named \"Shelf 4.2.1\" and a shelf action region.",
"dependencies": [
"REQ-4.1"
],
"parent": "REQ-4.2",
"scenarios": [
{
"name": "Enter Shelf Details Page",
"steps": [
"GIVEN: The user is on the shelf list page and at least one shelf is visible.",
"WHEN: The user activates the unique link or button named `Shelf 4.2.1` in the shelf list.",
"THEN: The system displays the shelf details page with a visible heading named `Shelf 4.2.1`."
]
}
]
},
{
"id": "REQ-4.3",
"type": "FOLDER",
"name": "Create New Shelf",
"description": "Provide a shelf creation flow with fields for shelf name, description, and tags. Reference image",
"dependencies": [
"REQ-4.2"
],
"parent": "REQ-4"
},
{
"id": "REQ-4.3.1",
"type": "ATOMIC",
"name": "Create Shelf",
"description": "Create a shelf from the shelf creation form. The form is exposed as role `form` named `Create shelf form` and contains uniquely labelled textboxes `Name` and `Description`, a control named `Shelf Tags` that reveals a textbox with exact placeholder `tag1, tag2`, a button named `Save Shelf`, and a button named `Cancel`. Seed data: shelf \"Shelf 4.3.1\".",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-4.3",
"scenarios": [
{
"name": "Create Shelf",
"steps": [
"GIVEN: The user is on the shelf details page and can access the action panel.",
"WHEN: The user activates the unique button named `New Shelf`, fills `Name` with `Shelf Created 4.3.1`, fills `Description` with `Shelf created by REQ-4.3.1.`, activates `Shelf Tags`, fills the revealed `tag1, tag2` textbox with `created, shelf`, and activates the `Save Shelf` button.",
"THEN: The system persists the shelf and displays the shelf list with exactly one entry named `Shelf Created 4.3.1`."
]
}
]
},
{
"id": "REQ-4.3.2",
"type": "ATOMIC",
"name": "Cancel Creation",
"description": "Exit the shelf creation flow without saving a new shelf. The creation form has a unique button named `Cancel`. Seed data: shelf \"Shelf 4.3.2\".",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-4.3",
"scenarios": [
{
"name": "Cancel Creation",
"steps": [
"GIVEN: The user is on the shelf creation page.",
"WHEN: The user activates the unique `Cancel` button.",
"THEN: The system returns to the shelf list and does not persist any shelf entered in the cancelled form."
]
}
]
},
{
"id": "REQ-4.4",
"type": "FOLDER",
"name": "Delete Shelf",
"description": "Delete the current shelf from the shelf details flow with confirmation. Confirmation page",
"dependencies": [
"REQ-4.2"
],
"parent": "REQ-4"
},
{
"id": "REQ-4.4.1",
"type": "ATOMIC",
"name": "Confirm Delete Shelf",
"description": "Delete a shelf after the user confirms the action. The details action area contains a unique button named `Delete`. Confirmation displays a dialog or confirmation page containing a unique button named `Confirm Delete` and a unique button named `Cancel`. Seed data: deletable shelf \"Shelf 4.4.1\".",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-4.4",
"scenarios": [
{
"name": "Confirm Delete Shelf",
"steps": [
"GIVEN: The user is on the shelf details page and can access the action panel.",
"WHEN: The user activates `Delete`, then activates the unique `Confirm Delete` control on the confirmation view.",
"THEN: The system deletes the shelf, returns to the shelf list page, and the entry named `Shelf 4.4.1` is absent."
]
}
]
},
{
"id": "REQ-4.4.2",
"type": "ATOMIC",
"name": "Cancel Delete Shelf",
"description": "Exit the delete flow without deleting the shelf. The confirmation view contains a unique button named `Cancel`. Seed data: deletable shelf \"Shelf 4.4.2\".",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-4.4",
"scenarios": [
{
"name": "Cancel Delete Shelf",
"steps": [
"GIVEN: The user is on the delete shelf confirmation page.",
"WHEN: The user activates the unique `Cancel` button.",
"THEN: The system returns to the shelf details page and keeps the shelf named `Shelf 4.4.2` unchanged."
]
}
]
},
{
"id": "REQ-4.5",
"type": "FOLDER",
"name": "Edit Shelf",
"description": "Provide a shelf editing flow for changing shelf information, related books, and tags. Shelf edit page",
"dependencies": [
"REQ-4.2"
],
"parent": "REQ-4"
},
{
"id": "REQ-4.5.1",
"type": "ATOMIC",
"name": "Save Shelf Edits",
"description": "Save changes made in the shelf edit form. The form is exposed as role `form` named `Edit shelf form` and contains uniquely labelled textboxes `Name` and `Description`, a `Shelf Tags` control with a `tag1, tag2` textbox, and a button named `Save Shelf`. Seed data: editable shelf \"Shelf 4.5.1\" with valid initial description and tags.",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-4.5",
"scenarios": [
{
"name": "Save Shelf Edits",
"steps": [
"GIVEN: The user is on the shelf details page and can access the action panel.",
"WHEN: The user activates `Edit`, fills `Name` with `Shelf Updated 4.5.1`, fills `Description` with `Shelf updated by REQ-4.5.1.`, activates `Shelf Tags`, fills `tag1, tag2` with `knowledge-base, docs`, and activates `Save Shelf`.",
"THEN: The system saves the changes and returns to a shelf details page displaying `Shelf Updated 4.5.1`."
]
}
]
},
{
"id": "REQ-4.5.2",
"type": "ATOMIC",
"name": "Cancel Shelf Edits",
"description": "Exit the shelf editing flow without saving changes. The edit form has a unique button named `Cancel`. Seed data: editable shelf \"Shelf 4.5.2\" with valid initial description and tags.",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-4.5",
"scenarios": [
{
"name": "Cancel Shelf Edits",
"steps": [
"GIVEN: The user is on the shelf edit page.",
"WHEN: The user activates the unique `Cancel` button.",
"THEN: The system returns to the shelf details page without applying the edits; `Shelf 4.5.2` remains unchanged."
]
}
]
},
{
"id": "REQ-5",
"type": "FOLDER",
"name": "Books Module",
"description": "Books contain a name, description, chapters, and pages. This module covers viewing books, opening book details, creating books, editing books, deleting books, and creating books from a shelf context. Book list page",
"dependencies": [
"REQ-1"
],
"parent": "ROOT"
},
{
"id": "REQ-5.1",
"type": "ATOMIC",
"name": "View Books List",
"description": "Open the books list page from the global navigation bar. The navigation control may be a link or button named exactly \"Books\". The page exposes a visible heading \"Books\" and a named region \"Book list\" containing the seeded book \"Book 5.1\" as a unique link or button.",
"dependencies": [
"REQ-1.1"
],
"parent": "REQ-5",
"scenarios": [
{
"name": "View Books List",
"steps": [
"GIVEN: The user is on a page where the global navigation bar is visible.",
"WHEN: The user activates the unique link or button named `Books` in the top navigation bar.",
"THEN: The system displays the books list page with heading `Books`, a `Book list` region, and the seeded book `Book 5.1` as a unique link or button."
]
}
]
},
{
"id": "REQ-5.2",
"type": "FOLDER",
"name": "Book Details Page",
"description": "Book details page that can be opened from supported book entry points and displays the selected book information. Book details page",
"dependencies": [
"REQ-5.1"
],
"parent": "REQ-5"
},
{
"id": "REQ-5.2.1",
"type": "ATOMIC",
"name": "Enter Book Details Page through Book List Page",
"description": "Open a book details page from the books list. The book list contains a unique link or button named exactly \"Book 5.2.1\". The destination displays a visible heading named \"Book 5.2.1\".",
"dependencies": [
"REQ-5.1"
],
"parent": "REQ-5.2",
"scenarios": [
{
"name": "Enter Book Details Page through Book List Page",
"steps": [
"GIVEN: The user is on the books list page and at least one book card is visible.",
"WHEN: The user activates the unique link or button named `Book 5.2.1` in the book list.",
"THEN: The system displays the book details page with a visible heading named `Book 5.2.1`."
]
}
]
},
{
"id": "REQ-5.2.2",
"type": "ATOMIC",
"name": "Enter Book Details Page through Shelf Details Page",
"description": "Open a book details page from a shelf details page. The shelf contains a unique link or button named exactly \"Book 5.2.2\". The destination displays a visible heading named \"Book 5.2.2\". Seed data: shelf \"Shelf 5.2.2\" containing book \"Book 5.2.2\" with valid initial metadata.",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-5.2",
"scenarios": [
{
"name": "Enter Book Details Page through Shelf Details Page",
"steps": [
"GIVEN: The user is on a shelf details page and at least one book is listed on the shelf.",
"WHEN: The user activates the unique link or button named `Book 5.2.2` in the shelf details page.",
"THEN: The system displays the book details page with a visible heading named `Book 5.2.2`."
]
}
]
},
{
"id": "REQ-5.3",
"type": "FOLDER",
"name": "Create Book in Book List Page",
"description": "Provide a book creation flow from the books list page with fields for name, rich-text description, optional cover image, book tags, and default page template. Reference image",
"dependencies": [
"REQ-5.1"
],
"parent": "REQ-5"
},
{
"id": "REQ-5.3.1",
"type": "ATOMIC",
"name": "Fill out and Save Book",
"description": "Create a new book from the books list page. The form is exposed as role `form` named `Create book form` and contains uniquely labelled textboxes `Name` and `Description`, a `Book Tags` control that reveals a `tag1, tag2` textbox, and a button named `Save Book`.",
"dependencies": [
"REQ-5.1"
],
"parent": "REQ-5.3",
"scenarios": [
{
"name": "Fill out and Save Book",
"steps": [
"GIVEN: The user is on the books list page and can access the action panel.",
"WHEN: The user activates `Create New Book`, fills `Name` with `Book Created 5.3.1`, fills `Description` with `Book created by REQ-5.3.1.`, activates `Book Tags`, fills `tag1, tag2` with `created, book`, and activates `Save Book`.",
"THEN: The system creates the book and opens its details page, displaying `Book Created 5.3.1` as a visible heading."
]
}
]
},
{
"id": "REQ-5.3.2",
"type": "ATOMIC",
"name": "Cancel Creating Book",
"description": "Exit the book creation flow without creating a book. The creation form contains a unique button named `Cancel`.",
"dependencies": [
"REQ-5.1"
],
"parent": "REQ-5.3",
"scenarios": [
{
"name": "Cancel Creating Book",
"steps": [
"GIVEN: The user is on the create new book page.",
"WHEN: The user activates the unique `Cancel` button.",
"THEN: The system returns to the books list and does not persist a book entered in the cancelled form."
]
}
]
},
{
"id": "REQ-5.4",
"type": "FOLDER",
"name": "Edit Book",
"description": "Provide a book editing flow for changing book metadata on the book details page. Reference image",
"dependencies": [
"REQ-5.2"
],
"parent": "REQ-5"
},
{
"id": "REQ-5.4.1",
"type": "ATOMIC",
"name": "Save Book Edits",
"description": "Save changes made in the book edit form. The form is exposed as role `form` named `Edit book form` and contains uniquely labelled textboxes `Name` and `Description`, a `Book Tags` control with a `tag1, tag2` textbox, and a button named `Save Book`. Seed data: editable book \"Book 5.4.1\" with valid initial description and tags.",
"dependencies": [
"REQ-5.2.1"
],
"parent": "REQ-5.4",
"scenarios": [
{
"name": "Save Book Edits",
"steps": [
"GIVEN: The user is on the book details page and can access the action panel.",
"WHEN: The user activates `Edit`, fills `Name` with `Book Updated 5.4.1`, fills `Description` with `Book updated by REQ-5.4.1.`, activates `Book Tags`, fills `tag1, tag2` with `manual, handbook`, and activates `Save Book`.",
"THEN: The system saves the changes and returns to a book details page displaying `Book Updated 5.4.1`."
]
}
]
},
{
"id": "REQ-5.4.2",
"type": "ATOMIC",
"name": "Cancel Book Edits",
"description": "Exit the book editing flow without saving changes. The edit form has a unique button named `Cancel`. Seed data: editable book \"Book 5.4.2\" with valid initial description and tags.",
"dependencies": [
"REQ-5.2.1"
],
"parent": "REQ-5.4",
"scenarios": [
{
"name": "Cancel Book Edits",
"steps": [
"GIVEN: The user is on the book edit page.",
"WHEN: The user activates the unique `Cancel` button.",
"THEN: The system returns to the book details page without applying the edits; `Book 5.4.2` remains unchanged."
]
}
]
},
{
"id": "REQ-5.5",
"type": "FOLDER",
"name": "Delete Book",
"description": "Delete the current book from the book details flow with confirmation. Confirmation page",
"dependencies": [
"REQ-5.2"
],
"parent": "REQ-5"
},
{
"id": "REQ-5.5.1",
"type": "ATOMIC",
"name": "Confirm Delete Book",
"description": "Delete a book after the user confirms the action. The details action area contains a unique button named `Delete`; the confirmation view contains a unique button named `Confirm Delete` and a unique button named `Cancel`. Seed data: deletable book \"Book 5.5.1\".",
"dependencies": [
"REQ-5.2.1"
],
"parent": "REQ-5.5",
"scenarios": [
{
"name": "Confirm Delete Book",
"steps": [
"GIVEN: The user is on the book details page and can access the action panel.",
"WHEN: The user activates `Delete`, then activates the unique `Confirm Delete` control.",
"THEN: The system deletes the book, returns to the books list page, and the entry named `Book 5.5.1` is absent."
]
}
]
},
{
"id": "REQ-5.5.2",
"type": "ATOMIC",
"name": "Cancel Delete Book",
"description": "Exit the delete flow without deleting the book. The confirmation view contains a unique button named `Cancel`. Seed data: deletable book \"Book 5.5.2\".",
"dependencies": [
"REQ-5.2.1"
],
"parent": "REQ-5.5",
"scenarios": [
{
"name": "Cancel Delete Book",
"steps": [
"GIVEN: The user is on the delete book confirmation page.",
"WHEN: The user activates the unique `Cancel` button.",
"THEN: The system returns to the book details page and keeps `Book 5.5.2` unchanged."
]
}
]
},
{
"id": "REQ-5.6",
"type": "FOLDER",
"name": "Create Book from Shelf Details Page",
"description": "Provide a book creation flow from a shelf details page so the created book is associated with the current shelf.",
"dependencies": [
"REQ-4.2"
],
"parent": "REQ-5"
},
{
"id": "REQ-5.6.1",
"type": "ATOMIC",
"name": "Fill out and Save Book with Shelf",
"description": "Create a new book from the current shelf context. The form has uniquely labelled textboxes `Name` and `Description`, a `Book Tags` control with a `tag1, tag2` textbox, and a button named `Save Book`. The created book remains associated with the current shelf. Seed data: shelf \"Shelf 5.6.1\".",
"dependencies": [
"REQ-4.2.1"
],
"parent": "REQ-5.6",
"scenarios": [
{
"name": "Fill out and Save Book with Shelf",
"steps": [
"GIVEN: The user is on a shelf details page and can access the action panel.",
"WHEN: The user activates `New Book`, fills `Name` with `Book Created 5.6.1`, fills `Description` with `Book created by REQ-5.6.1.`, activates `Book Tags`, fills `tag1, tag2` with `created, shelf-book`, and activates `Save Book`.",
"THEN: The system creates the book, associates it with `Shelf 5.6.1`, and displays both names on the resulting page."
]
}
]
},
{
"id": "REQ-6",
"type": "FOLDER",
"name": "Pages and Chapters Module",
"description": "Pages are the basic reading units of a book, and chapters organize groups of pages. This module covers page editing, draft handling, chapter creation, and page reading.",
"dependencies": [
"REQ-5"
],
"parent": "ROOT"
},
{
"id": "REQ-6.1",
"type": "FOLDER",
"name": "Page Edit Page",
"description": "Provide the page editing flow for creating pages, saving drafts, and deleting drafts. Page edit page Delete draft confirmation page",
"dependencies": [
"REQ-5.2"
],
"parent": "REQ-6"
},
{
"id": "REQ-6.1.1",
"type": "ATOMIC",
"name": "Save Page",
"description": "Create and save a new page in a book. The editor contains exactly one textbox with placeholder `Page title`, exactly one multiline textbox with placeholder `Write your page content here...`, and a button named `Save Page`. Seed data: book \"Book 6.1.1\".",
"dependencies": [
"REQ-5.2.1"
],
"parent": "REQ-6.1",
"scenarios": [
{
"name": "Save Page",
"steps": [
"GIVEN: The user is on a book details page.",
"WHEN: The user activates `New Page`, fills `Page title` with `Page Created 6.1.1`, fills `Write your page content here...` with `Page content created by REQ-6.1.1.`, and activates `Save Page`.",
"THEN: The system saves the page, adds exactly one entry named `Page Created 6.1.1` to the book, and returns to the book details page."
]
}
]
},
{
"id": "REQ-6.1.2",
"type": "ATOMIC",
"name": "Save Draft",
"description": "Save the current page content as a draft. The editor contains a textbox with placeholder `Page title`, a multiline textbox with placeholder `Write your page content here...`, and a button named `Save Draft`. Seed data: book \"Book 6.1.2\"; verified account with nickname \"BookStack User\", email \"bookstack_user@example.com\", and password \"Password123!\".",
"dependencies": [
"REQ-5.2.1"
],
"parent": "REQ-6.1",
"scenarios": [
{
"name": "Save Draft",
"steps": [
"GIVEN: The authenticated user is on the page edit page.",
"WHEN: The user fills `Page title` with `Page Draft 6.1.2`, fills `Write your page content here...` with `Draft content created by REQ-6.1.2.`, and activates `Save Draft`.",
"THEN: The system stores the draft and shows exactly one entry named `Page Draft 6.1.2` in the `My Recent Drafts` list on the homepage."
]
}
]
},
{
"id": "REQ-6.1.3",
